export const VOCABULARY_BY_ID = new Map(VOCABULARY.map(entry => [entry.wordId, entry]));
export const FIRST_LEARNING_PACK = VOCABULARY.filter(entry => entry.learningPack === 'LP01');

export function assertVocabularyIntegrity(): void {
  if (VOCABULARY.length !== 80) throw new Error(`Expected 80 vocabulary entries, got ${VOCABULARY.length}`);
  if (VOCABULARY_BY_ID.size !== 80) throw new Error('Vocabulary wordId values must be unique');
  if (VOCABULARY.some(entry => !entry.wordId || !entry.word || !entry.meaning)) throw new Error('Vocabulary source fields are incomplete');
  const l2 = VOCABULARY.filter(entry => entry.coverage.includes('L2')).length;
  const l3 = VOCABULARY.filter(entry => entry.coverage.includes('L3')).length;
  if (l2 !== 36 || l3 !== 24) throw new Error(`Unexpected coverage: L2=${l2}, L3=${l3}`);
}
